SELECT id, event_type, page, event_time, duration_sec, LAST_VALUE(page) IGNORE NULLS OVER w_recent AS last_known_page, AVG(duration_sec) OVER (PARTITION BY event_type ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS duration_sec_avg_2, NTILE(5) OVER (PARTITION BY page ORDER BY duration_sec DESC, id) AS duration_sec_bucket FROM web_events WINDOW w_recent AS (PARTITION BY page ORDER BY duration_sec, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
